groups={'endoderm':['endoderm'],'endostyle_csg':['endostyle_csg'],'epidermal_neural':['epidermal_neural1','epidermal_neural2'],'epidermis':['epidermis_1','epidermis_2'],'mesodermal_notochord':['mesodermal_notochord'],'muscular_somites':['muscular_somites'],'neural':['neural'],'neural_like':['neural_like1','neural_like2'],'putative_neuro_endo':['putative_neuro_endo'],'somite':['somite'],'tailbud':['tailbud'],'tailbud_neural':['tailbud_neural']}
meta_cell={}
with gzip.open('[REDACTED LOCAL PATH]','rt') as f:
    r=csv.reader(f,delimiter='\\t'); next(r)
    for row in r:
        if len(row)<4: continue
        meta_cell[row[3]]=row[1]
# read metacell matrix header
with gzip.open('[REDACTED LOCAL PATH]','rt') as f:
    r=csv.reader(f,delimiter='\\t'); header=next(r)
    print('meta header n', len(header), header[:5])
    sums={g:{'sum':{},'n':{}} for g in groups}
    for row in r:
        gid=row[0]
        for mc,val in zip(header,row[1:]):
            ct=meta_cell.get(mc)
            g=next((gr for gr,types in groups.items() if ct in types),None)
            if g:
                d=sums[g]['sum']; n=sums[g]['n']
                d[gid]=d.get(gid,0)+float(val)
                n[gid]=n.get(gid,0)+1
# load input genes and columns
with gzip.open('/workspace/inputs/sample.swap.rna.q1.tsv.gz','rt') as f:
    r=csv.reader(f,delimiter='\\t'); inhead=next(r)[1:]; genes=[row[0] for row in r]
# build ref averages
ref={g:{} for g in groups}
for g in groups:
    for gid in genes:
        if sums[g]['n'].get(gid):
            ref[g][gid]=sums[g]['sum'][gid]/sums[g]['n'][gid]
# read input col values
inp={g:{} for g in groups}
with gzip.open('/workspace/inputs/sample.swap.rna.q1.tsv.gz','rt') as f:
    r=csv.reader(f,delimiter='\\t'); next(r)
    for row in r:
        for g,v in zip(inhead,row[1:]): inp[g][row[0]]=float(v)
import scipy.stats as st
for gi in groups:
    xs=[inp[gi][gid] for gid in genes]
    best=[]
    for gr in groups:
        ys=[ref[gr].get(gid,0) for gid in genes]
        rp=st.pearsonr(xs,ys)[0]
        rs=st.spearmanr(xs,ys)[0]
        best.append((rp,rs,gr))
    best.sort(reverse=True)
    print(gi, [(round(a,3),round(b,3),n) for a,b,n in best[:3]])
