import json
import urllib.request
from concurrent.futures import ThreadPoolExecutor, as_completed
history_id = 'bbd44e69cb8906b5a35709fd765e28c2'
input_id = 'f9cad7b01a4721351ca88276438f1fc3'
blocks = [(1322 + 1000*i, 2321 + 1000*i) for i in range(20)] + [(21322, 21452)]
galaxy_key = open('[REDACTED LOCAL PATH]').read().strip()

def submit(block):
    start, end = block
    inputs = {'input1': {'src': 'hda', 'id': input_id}, 'groupcol': '1', 'ignorecase': False}
    for i, col in enumerate(range(start, end + 1)):
        inputs[f'operations_{i}|optype'] = 'mean'
        inputs[f'operations_{i}|opcol'] = str(col)
        inputs[f'operations_{i}|opround'] = 'no'
        inputs[f'operations_{i}|opdefault'] = '0'
    payload = {'tool_id': 'Grouping1', 'history_id': history_id, 'inputs': inputs}
    req = urllib.request.Request('https://usegalaxy.org/api/tools', data=json.dumps(payload).encode(), headers={'x-api-key': galaxy_key, 'content-type': 'application/json'}, method='POST')
    with urllib.request.urlopen(req, timeout=900) as resp:
        data = json.load(resp)
    return {'start':start, 'end':end, 'job':data['jobs'][0]['id'], 'output':data['outputs'][0]['id']}

with ThreadPoolExecutor(max_workers=3) as pool:
    futures = {pool.submit(submit, block): block for block in blocks}
    for future in as_completed(futures):
        block = futures[future]
        try:
            print(json.dumps(submit_result := future.result()), flush=True)
        except Exception as exc:
            print(json.dumps({'start':block[0], 'end':block[1], 'error':repr(exc)}), flush=True)
